generator client {
  provider = "prisma-client"
  output   = "../src/generated/prisma"
}

datasource db {
  provider = "postgresql"
}

model User {
  id        Int      @id @default(autoincrement())
  email     String   @unique
  name      String?
  age       Int?
  active    Boolean  @default(true)
  createdAt DateTime @default(now())
  tags      String[]
  profile   Json?
  posts     Post[]
}

model Post {
  id        Int     @id @default(autoincrement())
  title     String
  published Boolean @default(false)
  authorId  Int
  author    User    @relation(fields: [authorId], references: [id])
}

import "dotenv/config";
import { defineConfig, env } from "prisma/config";
export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: { path: "prisma/migrations" },
  datasource: { url: env("DATABASE_URL") }
});

import "dotenv/config";
import { PrismaClient } from "./generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
const connectionString = process.env.DATABASE_URL;
if (!connectionString)
  throw new Error("DATABASE_URL is required");
const adapter = new PrismaPg({ connectionString });
const prisma = new PrismaClient({ adapter });

generator client {
  provider = "prisma-client"
  output   = "../src/generated/prisma"
}

await prisma.user.findMany({
  where: {
    active: true,
    OR: [{ age: { gte: 20 } },
      { age: null }]
  }
});

await prisma.user.findMany({
  where: {
    email: { contains: 'example.com', mode: 'insensitive' }
  }
});

await prisma.user.findMany({
  cursor: { id: 100 },
  skip: 1,
  take: 10,
  orderBy: { id: 'asc' }
});

await prisma.user.findMany({ distinct: ['name'], select: {
    name: true
  } });

await prisma.user.create({
  data: { email: 'pomo@example.com', name: 'Pomo', tags: [] }
});

await prisma.user.createMany({
  data: [{ email: 'a@example.com', tags: [] },
    { email: 'b@example.com', tags: [] }],
  skipDuplicates: true
});

await prisma.user.upsert({
  where: { email: 'pomo@example.com' },
  update: { name: 'New' },
  create: { email: 'pomo@example.com', tags: [] }
});

await prisma.user.create({
  data: {
    email: 'nested@example.com',
    tags: [],
    posts: { create: { title: 'Hello' } }
  }
});

await prisma.post.create({
  data: { title: 'Hello', author: { connect: { id: 1 } } }
});

await prisma.$transaction(async (tx) => {
  const user = await tx.user.create({ data: { email: 'tx@example.com', tags: [] } });
  await tx.post.create({ data: { title: 'Hello', authorId: user.id } });
});

import { Prisma } from './generated/prisma/client';
try {
  await prisma.user.create({ data: { email: 'pomo@example.com', tags: [] } });
}
catch (e) {
  if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === 'P2002') {
    console.log('一意制約違反');
  }
  else {
    throw e;
  }
}
